<?php
/** @var array{css:?string,js:?string} $assets */
/** @var array<int,array<string,string>> $navigation */
/** @var array<string,string> $period */
/** @var array<string,mixed> $vehicle */
$money = static fn (float $value): string => ($value < 0 ? '−' : '') . '$' . number_format(abs($value), 2);
$backQuery = http_build_query(['period' => $period['preset'], 'from' => $period['from'], 'to' => $period['to_inclusive']]);
$sectionLabels = ['turo_transaction' => 'Turo revenue and recoveries', 'operating_expense' => 'Generic operating expenses', 'maintenance_log' => 'Maintenance', 'charging_session' => 'Charging', 'airport_operations_expense_allocation' => 'Airport allocations'];
$sections = [];
foreach ($vehicle['activities'] as $activity) {
    $sections[$activity['source_type']][] = $activity;
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= esc((string) $vehicle['vehicle_label']) ?> Financial Results | FleetOS</title><?php if ($assets['css'] !== null): ?><link rel="stylesheet" href="/build/<?= esc($assets['css'], 'attr') ?>"><?php endif; ?></head>
<body class="fleet-shell"><a class="skip-link" href="#main-content">Skip to main content</a><div class="app-frame financial-results-frame"><?= view('fleet_command_center/components/navigation', ['items' => $navigation]) ?><main id="main-content" class="command-main operator-main financial-results-main" tabindex="-1"><header class="top-status"><div><p class="eyebrow">Vehicle attributable detail</p><h1><?= esc((string) $vehicle['vehicle_label']) ?></h1><p class="status-copy"><?= esc($period['label']) ?> · Source-backed realized and recorded activity.</p></div><a class="action-link" href="/reports/vehicle-financial-results?<?= esc($backQuery, 'attr') ?>">All vehicle results</a></header>
<section class="section"><div class="financial-report-summary vehicle-detail-summary"><article><span>Attributable Realized Operating Revenue</span><strong><?= esc($money((float) $vehicle['realized_operating_revenue'])) ?></strong></article><article><span>Attributable Realized Recoveries</span><strong><?= esc($money((float) $vehicle['realized_recoveries'])) ?></strong></article><article><span>Attributable Recorded Operating Costs</span><strong><?= esc($money((float) $vehicle['recorded_operating_costs'])) ?></strong></article><article><span>Attributable Net Realized Operating Result</span><strong><?= esc($money((float) $vehicle['net_realized_operating_result'])) ?></strong></article></div><p class="muted">Fleet-wide and unallocated costs are intentionally excluded from this vehicle result.</p></section>
<section class="section" aria-labelledby="supporting-detail-heading"><div class="section-heading"><div><p class="eyebrow">Supporting facts</p><h2 id="supporting-detail-heading">Source activity</h2></div></div><?php if ($sections === []): ?><div class="empty-state">No attributable realized or recorded activity exists for this vehicle in the selected period.</div><?php endif; ?><?php foreach ($sectionLabels as $sourceType => $label): ?><?php if (($sections[$sourceType] ?? []) === []) {
    continue;
} ?><section class="financial-source-section"><h3><?= esc($label) ?></h3><div class="financial-table-scroll"><table class="financial-source-table"><thead><tr><th scope="col">Date</th><th scope="col">Description</th><th scope="col">Basis</th><th scope="col" class="numeric">Amount</th></tr></thead><tbody><?php foreach ($sections[$sourceType] as $activity): ?><tr><td><?= esc((string) $activity['occurred_on']) ?></td><td><?php if (($activity['source_link'] ?? null) !== null): ?><a class="text-link" href="<?= esc((string) $activity['source_link'], 'attr') ?>"><?= esc((string) $activity['description']) ?></a><?php else: ?><?= esc((string) $activity['description']) ?><?php endif; ?></td><td><?= esc(ucwords(str_replace('_', ' ', (string) $activity['allocation_state']))) ?></td><td class="numeric"><?= esc($money((float) $activity['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?></section>
<?= view('fleet_command_center/components/footer') ?></main></div><?php if ($assets['js'] !== null): ?><script type="module" src="/build/<?= esc($assets['js'], 'attr') ?>"></script><?php endif; ?></body></html>
